def apply(text, cfg=None):
    """Return text rewritten for SPEECH only (printing should use the original)."""
    if not text:
        return text
    table = dict(DEFAULT)                       # {"the owner": "Renee", ...}
    table.update((cfg or {}).get("voice", {}).get("pronunciation", {}) or {})
    for word, say in table.items():
        if not word or word.startswith("_") or not isinstance(say, str):
            continue
        pattern = re.compile(r"\b" + re.escape(word) + r"\b", re.IGNORECASE)
        text = pattern.sub(lambda m, s=say: _match_case(m.group(0), s), text)
    return text

