def stream_reply(messages, config=None):
    config = config or load_config()
    chain = enabled_chain(config)
    if not chain:
        raise RuntimeError("No LLM backend enabled in config.json")
    last_err = None
    for name in chain:
        try:
            cfg = config["backends"]["providers"][name]
            first = True
            for chunk in _STREAMERS[name](messages, cfg):
                if first:
                    yield ("__provider__", name); first = False
                yield (name, chunk)
            if not first:
                return                       # produced output successfully
        except Exception as e:
            last_err = e
            sys.stderr.write(f"[backend '{name}' failed: {e}; trying next]\n")
            continue
    raise RuntimeError(f"All enabled backends failed. Last error: {last_err}")

def stream_ollama(messages, cfg):
    import requests
    host = cfg.get("host", "http://localhost:11434").rstrip("/")
    r = requests.post(f"{host}/api/chat",
                      json={"model": cfg["model"], "messages": messages, "stream": True},
                      stream=True, timeout=120)
    r.raise_for_status()
    for line in r.iter_lines():
        if not line:
            continue
        obj = json.loads(line.decode("utf-8"))
        chunk = obj.get("message", {}).get("content", "")
        if chunk:
            yield chunk
        if obj.get("done"):
            break

